// This script parses the Trendlyne URL to get the unique screen ID.
const link = items[0].json.link;
const parts = link.split('/');

// The ID is the number right after 'stock-screener' in the URL
const screenId = parts[parts.indexOf('stock-screener') + 1];

if (!screenId) {
  throw new Error('Could not parse screenId from Trendlyne link.');
}

// Add the screenId to the data for the next step
return [{
  json: {
    ...items[0].json,
    screenId: screenId
  }
}];

