// This script navigates to a Trendlyne screener, clicks the export buttons,
// and captures the downloaded CSV file.

// --- 1. Get Inputs ---
const { link, trendlyneCookies } = $json;
if (!link || !link.includes('trendlyne.com')) {
    throw new Error('A valid Trendlyne link was not provided.');
}
if (!trendlyneCookies || !Array.isArray(trendlyneCookies)) {
    throw new Error('Trendlyne cookies were not provided.');
}

// --- 2. Setup Page and Cookies ---
await $page.setCookie(...trendlyneCookies);
console.log('Successfully set Trendlyne cookies.');

// --- 3. Intercept Downloads using CDP ---
const client = await $page.target().createCDPSession();
await client.send('Page.setDownloadBehavior', {
    behavior: 'allowAndName',
    downloadPath: '/dev/null',
    eventsEnabled: true,
});

const downloadPromise = new Promise((resolve, reject) => {
    let downloadInfo = {};
    client.on('Page.downloadWillBegin', (event) => {
        downloadInfo.fileName = event.suggestedFilename;
        console.log(`Trendlyne download started: ${downloadInfo.fileName}`);
    });
    client.on('Page.downloadProgress', (event) => {
        if (event.state === 'completed') {
            downloadInfo.data = event.data;
            resolve(downloadInfo);
        } else if (event.state === 'canceled') {
            reject(new Error('Download was canceled.'));
        }
    });
    setTimeout(() => {
        reject(new Error('Download timed out after 30 seconds.'));
    }, 30000);
});

// --- 4. Navigate and Perform Clicks ---
await $page.goto(link, { waitUntil: 'networkidle2' });
console.log(`Mapsd to Trendlyne link: ${link}`);

// Click the main export dropdown button
await $page.waitForSelector('#exportOptionContainer', { visible: true });
await $page.click('#exportOptionContainer');
console.log('Clicked main export container.');

// Wait for the "This Table" option to appear and click it.
// --- THIS IS THE CORRECTED LINE ---
const downloadButtonXPath = "//*[contains(text(), 'This Table')]";
await $page.waitForSelector(`xpath/${downloadButtonXPath}`, { visible: true });
const [downloadButton] = await $page.$$(`xpath/.${downloadButtonXPath}`);

if (!downloadButton) {
    throw new Error('Could not find the "This Table" button in the dropdown.');
}
await downloadButton.click();
console.log('Clicked "This Table". Waiting for download to complete...');


// --- 5. Await Download and Return Data ---
const { fileName, data } = await downloadPromise;
console.log(`Download captured successfully: ${fileName}`);

await client.detach();

// Return the filename and the Base64 data for the next nodes
return [{
    json: {
        ...$json, // Pass along all previous data
        fileName: fileName,
        data: data, // The Base64 string
    }
}];

