// Get the starting range info from our first node in the loop
const rangeData = $('Calculate Index & Range').item.json;
const col_letter = rangeData.col_letter;
const start_row = rangeData.start_row;

// Get the response data from the Trendlyne API call
const apiResponse = items[0].json.body;
const headers = apiResponse.tableHeaders;
const dataRows = apiResponse.tableData;

if (!dataRows || dataRows.length === 0) {
  console.log("API returned no data rows. Skipping.");
  return []; // Return empty to stop this branch
}

// Find the column indices for both NSE and BSE codes for fallback
const nseCodeIndex = headers.findIndex(header => header.unique_name === 'NSEcode');
const bseCodeIndex = headers.findIndex(header => header.unique_name === 'BSEcode');

if (nseCodeIndex === -1) {
  throw new Error("Could not find 'NSEcode' column in the API response headers.");
}

// Create a simple list of codes, using BSE as a fallback (same as Screener logic)
const codeList = dataRows.map(row => {
  let code = row[nseCodeIndex];
  // Use BSE code if NSE code is missing and BSE index was found
  if (!code && bseCodeIndex !== -1) {
    code = row[bseCodeIndex];
  }
  return code ? String(code) : "";
});

// Format the list for the Google Sheets API (e.g., [ ["TVSLTD"], ["RECLTD"] ])
const valuesForApi = codeList.map(code => [code]);

// Calculate the end row and create the full range string (e.g., "B7:B16")
const end_row = start_row + dataRows.length - 1;
const fullRange = `${col_letter}${start_row}:${col_letter}${end_row}`;

// Return a single item with all the data needed for the final step
return [{
  json: {
    ...rangeData, // Pass along original data
    fullRange: fullRange,
    valuesForApi: valuesForApi,

  }
}];
